def summarise(frame):
    keys = [X_FIELD] + ([GROUP] if GROUP is not None else [])
    # sort=False keeps the file's category order instead of an alphabetical one.
    grouped = frame.groupby(keys, as_index=False, sort=False)[Y_FIELD]
